resource "aws_iam_role_policy" "assume_deploy" {
  name = "assume-deploy"
  role = aws_iam_role.ci.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = var.deploy_role_arn
      }
    ]
  })
}

variable "deploy_role_arn" {
  type = string
}

resource "aws_iam_role" "decryptor" {
  name = "kms-decryptor"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = { Service = "ecs-tasks.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "decrypt" {
  name = "kms-decrypt"
  role = aws_iam_role.decryptor.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
        ]
        Resource = var.kms_key_arn
      }
    ]
  })
}

variable "kms_key_arn" {
  type = string
}

resource "aws_iam_role" "analyst" {
  name = "analyst-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = { AWS = var.analyst_root_arn }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "analyst" {
  for_each = toset(var.managed_policy_arns)

  role       = aws_iam_role.analyst.name
  policy_arn = each.value
}

variable "analyst_root_arn" {
  type = string
}

variable "managed_policy_arns" {
  type = list(string)
  default = [
    "arn:aws:iam::aws:policy/AmazonAthenaFullAccess",
    "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess",
  ]
}
